def annotate_source(tree: ast.AST, source: str) -> ast.AST:
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float):
            node.numeric_lexeme = ast.get_source_segment(source, node)
        if isinstance(node, ast.Call):
            location = f"{source}\0{node.lineno}:{node.col_offset}:{node.end_col_offset}"
            node.call_site_id = hashlib.sha256(location.encode()).hexdigest()[:24]
    return tree

def source_expression(node: ast.AST, source: str | None = None) -> str:
    """Unparse syntax, never the rounded float stored by Python's parser."""
    tree = copy.deepcopy(node)
    if source is not None:
        annotate_source(tree, source)
    names = {item.id for item in ast.walk(tree) if isinstance(item, ast.Name)}
    replacements = {}

    class Tokens(ast.NodeTransformer):
        def visit_Constant(self, item):
            token = getattr(item, "numeric_lexeme", None)
            if token is None:
                return item
            name = f"_numeric_token_{len(replacements)}"
            while name in names:
                name += "_"
            names.add(name)
            replacements[name] = token
            return ast.copy_location(ast.Name(id=name, ctx=ast.Load()), item)

    rendered = ast.unparse(Tokens().visit(tree))
    return re.sub(r"\b_numeric_token_\d+_*\b", lambda m: replacements.get(m[0], m[0]), rendered)

def rational_constant(node):
    if isinstance(node, ast.Constant) and type(node.value) in (int, float):
        if type(node.value) is int:
            return Fraction(node.value)
        token = getattr(node, "numeric_lexeme", None)
        if token is not None:
            return Fraction(token)
        # An unannotated Python float has already lost the original literal.
        # Decline a proof rather than guess that rounded value was intended.
        raise ValueError("missing exact numeric token")
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.UAdd | ast.USub):
        value = rational_constant(node.operand)
        return value if isinstance(node.op, ast.UAdd) else -value
    if isinstance(node, ast.BinOp):
        left, right = rational_constant(node.left), rational_constant(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
    raise ValueError("not a rational constant")

def zero_test_call(expression):
    """Remove only rational operations preserving the entire residual's zeros."""
    try:
        node = annotate_source(ast.parse(expression, mode="eval"), expression).body
    except (SyntaxError, TypeError):
        return None

    def constant(node):
        try:
            return rational_constant(node)
        except (ValueError, ArithmeticError):
            return None

    while True:
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.UAdd | ast.USub):
            node = node.operand
        elif isinstance(node, ast.BinOp):
            left, right = constant(node.left), constant(node.right)
            if isinstance(node.op, ast.Mult):
                if left is not None and left != 0:
                    node = node.right
                elif right is not None and right != 0:
                    node = node.left
                else:
                    return None
            elif isinstance(node.op, ast.Div) and right is not None and right != 0:
                node = node.left
            elif isinstance(node.op, ast.Add | ast.Sub):
                if right == 0:
                    node = node.left
                elif left == 0:
                    node = node.right
                else:
                    return None
            else:
                return None
        else:
            return node if isinstance(node, ast.Call) else None

def contact_tangency_source(left, right, constructions, equalities=()):
    """Return a contact-radius dot product, or None without proven incidence."""
    definitions = {name: _parse(source) for name, source in constructions}

    def resolve(node):
        seen = set()
        while isinstance(node, ast.Name) and node.id in definitions:
            if node.id in seen:
                raise ValueError("cyclic construction")
            seen.add(node.id)
            node = definitions[node.id]
        return node

    def canonical(node, active=frozenset()):
        if isinstance(node, ast.Name) and node.id in definitions:
            if node.id in active:
                raise ValueError("cyclic construction")
            return canonical(definitions[node.id], active | {node.id})
        try:
            return ("rational", rational_constant(node))
        except (ValueError, ArithmeticError):
            if isinstance(node, ast.Constant) and type(node.value) is float:
                raise ValueError("missing exact numeric token") from None
        if isinstance(node, ast.AST):
            return (
                type(node).__name__,
                tuple(
                    (name, canonical(value, active))
                    for name, value in ast.iter_fields(node)
                    if name not in {"ctx"}
                ),
            )
        if isinstance(node, list):
            return tuple(canonical(value, active) for value in node)
        return node

    def call(node, name, arity):
        return (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == name
            and len(node.args) == arity
            and not node.keywords
        )

    equations, zero_calls, candidates = [], [], []
    for lhs, rhs in equalities:
        a, b = _parse(lhs), _parse(str(rhs))
        equations.extend(((a, b), (b, a)))
        try:
            is_zero = rational_constant(b) == 0
        except (ValueError, ArithmeticError):
            is_zero = False
        if is_zero:
            node = zero_test_call(lhs)
            if node is not None:
                zero_calls.append(node)
                if node.args:
                    candidates.append(node.args[0])
    candidates.extend(ast.Name(id=name, ctx=ast.Load()) for name in definitions)

    def same(a, b):
        return canonical(a) == canonical(b)

    def circle_contains(point, circle_source):
        circle_ast = _parse(circle_source)
        circle_node = resolve(circle_ast)
        center_ast = (
            circle_node.args[0]
            if call(circle_node, "Circle", 2)
            else _parse(f"Center({circle_source})")
        )
        radius_ast = (
            circle_node.args[1]
            if call(circle_node, "Circle", 2)
            else _parse(f"Radius({circle_source})")
        )
        if call(circle_node, "Circumcircle", 3) and any(same(point, p) for p in circle_node.args):
            return True
        built = resolve(point)
        if isinstance(built, ast.Call) and isinstance(built.func, ast.Name):
            if built.func.id == "Intersect" and any(same(arg, circle_ast) for arg in built.args):
                return True
            if (
                built.func.id == "IncircleContactPoint"
                and call(circle_node, "Incircle", 3)
                and len(built.args) >= 3
                and all(same(a, b) for a, b in zip(built.args[:3], circle_node.args, strict=True))
            ):
                return True
        if any(
            call(n, "OnCircle", 2) and same(n.args[0], point) and same(n.args[1], circle_ast)
            for n in zero_calls
        ):
            return True
        return any(
            call(resolve(a), "Distance", 2)
            and same(b, radius_ast)
            and {canonical(arg) for arg in resolve(a).args}
            == {canonical(point), canonical(center_ast)}
            for a, b in equations
        )

    try:
        left_node, right_node = (
            _parse(left),
            _parse(right),
        )
        for line_node, circle_node, circle_source in (
            (resolve(left_node), resolve(right_node), right),
            (resolve(right_node), resolve(left_node), left),
        ):
            if not call(line_node, "Line", 2):
                continue
            if not (
                call(circle_node, "Circle", 2)
                or call(circle_node, "Circumcircle", 3)
                or call(circle_node, "Incircle", 3)
            ):
                continue

            def line_contains(point, line_node=line_node):
                if any(same(point, p) for p in line_node.args):
                    return True
                built = resolve(point)
                if (
                    isinstance(built, ast.Call)
                    and isinstance(built.func, ast.Name)
                    and built.func.id == "Intersect"
                    and any(same(arg, line_node) for arg in built.args)
                ):
                    return True
                for n in zero_calls:
                    if (
                        call(n, "OnLine", 2)
                        and same(n.args[0], point)
                        and same(n.args[1], line_node)
                    ):
                        return True
                    if (
                        call(n, "OnLine", 3)
                        and same(n.args[0], point)
                        and {canonical(arg) for arg in n.args[1:]}
                        == {canonical(arg) for arg in line_node.args}
                    ):
                        return True
                    if call(n, "Collinear", 3) and {canonical(arg) for arg in n.args} == {
                        canonical(point),
                        *(canonical(arg) for arg in line_node.args),
                    }:
                        return True
                return False

            contact = next(
                (
                    p
                    for p in (*line_node.args, *candidates)
                    if circle_contains(p, circle_source) and line_contains(p)
                ),
                None,
            )
            if contact is None:
                continue
            a, b = (f"({source_expression(point)})" for point in line_node.args)
            p = f"({source_expression(contact)})"
            center = f"Center({circle_source})"
            return (
                f"(({center}.x-{p}.x)*({b}.x-{a}.x)+({center}.y-{p}.y)*({b}.y-{a}.y))"
                f"/Distance({a},{b})"
            )

        def is_circle(node):
            return (
                call(node, "Circle", 2)
                or call(node, "Circumcircle", 3)
                or call(node, "Incircle", 3)
            )

        if is_circle(resolve(left_node)) and is_circle(resolve(right_node)):
            contact = next(
                (p for p in candidates if circle_contains(p, left) and circle_contains(p, right)),
                None,
            )
            if contact is not None:
                p = f"({source_expression(contact)})"
                a, b = f"Center({left})", f"Center({right})"
                # Given a shared point, tangent circles have collinear radii.
                # This cross product has a simple zero at a contact, whereas
                # the distance between centers has a double zero.
                return f"(({a}.x-{p}.x)*({b}.y-{p}.y)-({a}.y-{p}.y)*({b}.x-{p}.x))/Radius({left})"
    except (ValueError, TypeError, RecursionError):
        return None
    return None

def distance_contact_sources(constructions, equalities):
    """Prove contacts expressed as Distance(center,line)=circle radius.

    Only an exactly matching Circle(center,radius) construction supplies the
    circle. The contact itself still needs an independent incidence proof.
    """
    definitions = {name: _parse(source) for name, source in constructions}

    def resolve(node):
        seen = set()
        while isinstance(node, ast.Name) and node.id in definitions:
            if node.id in seen:
                raise ValueError("cyclic construction")
            seen.add(node.id)
            node = definitions[node.id]
        return node

    def call(node, name, count):
        return (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == name
            and len(node.args) == count
            and not node.keywords
        )

    def same(a, b):
        return source_expression(resolve(a)) == source_expression(resolve(b))

    result = {}
    try:
        circles = [(name, resolve(node)) for name, node in definitions.items()]
        circles = [(name, node) for name, node in circles if call(node, "Circle", 2)]
        for index, (lhs, rhs) in enumerate(equalities):
            a, b = _parse(lhs), _parse(str(rhs))
            for distance, radius in ((resolve(a), b), (resolve(b), a)):
                if not call(distance, "Distance", 2):
                    continue
                for point, line in (
                    (distance.args[0], distance.args[1]),
                    (distance.args[1], distance.args[0]),
                ):
                    if not call(resolve(line), "Line", 2):
                        continue
                    for name, circle in circles:
                        if not same(point, circle.args[0]) or not same(radius, circle.args[1]):
                            continue
                        source = contact_tangency_source(
                            source_expression(line), name, constructions, equalities
                        )
                        if source is not None:
                            result[index] = source
        return result
    except (ValueError, TypeError, RecursionError):
        return {}

def distance_radius_sources(constructions, equalities):
    """Match the frozen Distance/Line/Circle syntax, without requiring contact.

    T1 uses the normalized line coefficients, not a contact point.  Resolve
    aliases exactly as distance_contact_sources does; do not infer incidence.
    """
    from geosolver.engine.standard.problem.tangency_contacts import _parse
    from geosolver.problem.expression_source import source_expression

    definitions = {name: _parse(source) for name, source in constructions}

    def resolve(node):
        seen = set()
        while isinstance(node, ast.Name) and node.id in definitions:
            if node.id in seen:
                raise ValueError("cyclic construction")
            seen.add(node.id)
            node = definitions[node.id]
        return node

    def call(node, name):
        return (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == name
            and len(node.args) == 2
            and not node.keywords
        )

    def same(a, b):
        return source_expression(resolve(a)) == source_expression(resolve(b))

    result = {}
    try:
        circles = [(name, resolve(node)) for name, node in definitions.items()]
        circles = [(name, node) for name, node in circles if call(node, "Circle")]
        for index, (lhs, rhs) in enumerate(equalities):
            a, b = _parse(lhs), _parse(str(rhs))
            for distance, radius in ((resolve(a), b), (resolve(b), a)):
                if not call(distance, "Distance"):
                    continue
                for point, line in (distance.args, distance.args[::-1]):
                    if not call(resolve(line), "Line"):
                        continue
                    for name, circle in circles:
                        if not same(point, circle.args[0]) or not same(radius, circle.args[1]):
                            continue
                        line_source = f"({source_expression(line)})"
                        delta = (
                            f"({line_source}.a*Center({name}).x"
                            f"+{line_source}.b*Center({name}).y+{line_source}.c)"
                        )
                        result[index] = f"{delta}**2-Radius({name})**2"
        return result
    except (ValueError, TypeError, RecursionError):
        return {}

def _zero_constraint_plans(constraints, targets):
    from geosolver.engine.standard.problem.zero_test_source import zero_test_call

    plans = {}
    for index, expression in enumerate(constraints):
        if index >= len(targets) or not _is_zero_target(targets[index]):
            continue
        node = zero_test_call(expression)
        if not isinstance(node, ast.Call) or node.keywords or len(node.args) != _BINARY_ARITY:
            continue
        if not isinstance(node.func, ast.Name):
            continue
        kind = node.func.id.lower()
        if kind in {"distance", "istangent"}:
            plans[index] = kind, tuple(ast.get_source_segment(expression, arg) for arg in node.args)
    return plans
